#chaptercontent@html
<js>
var t = String(result);
t = t.replace(/<br\s*\/?>/gi, '\n');
t = t.replace(/<\/p>/gi, '\n');
t = t.replace(/<(p|div)[^>]*>/gi, '\n');
t = t.replace(/<[^>]+>/g, '');
t = t.replace(/本文链接[:：]?\s*\S*/g, '');
t = t.replace(/本章还未完[^\n]*/g, '');
t = t.replace(/本章未完[^\n]*/g, '');
t = t.replace(/\(\d+\/\d+\)/g, '');
t = t.replace(/[ \t\u00a0]+/g, ' ');
t = t.replace(/\n\s*\n/g, '\n');
t = t.replace(/^\s+|\s+$/g, '');
t.trim();
</js>
